map $remote_addr $adaptive_profile {
    include /etc/nginx/maps/redirect_map.conf;
}

map $adaptive_profile $adaptive_backend {
    default     http://127.0.0.1:8080;
    real        http://127.0.0.1:8080;
    wordpress   http://10.10.10.2:8084;
    phpmyadmin  http://10.10.10.2:8084;
    snare       http://10.10.10.2:8084;
    rabbithole  http://10.10.10.2:8084;
}

log_format adaptive_json escape=json '{"timestamp":"$time_iso8601",'
  '"source_ip":"$remote_addr","forwarded_for":"$proxy_add_x_forwarded_for",'
  '"protocol":"$scheme","profile":"$adaptive_profile","status":$status,'
  '"request":"$request","upstream":"$upstream_addr"}';

server {
    listen 192.168.56.10:80;
    server_name defender.lab;
    access_log /var/log/nginx/adaptive_access.json adaptive_json;

    location / {
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Real-Port $remote_port;
        proxy_set_header X-Forwarded-Port $server_port;
        proxy_set_header X-Request-ID $request_id;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto http;
        proxy_pass $adaptive_backend;
    }
}

server {
    listen 192.168.56.10:443 ssl;
    server_name defender.lab;
    ssl_certificate /etc/trap/lab.crt;
    ssl_certificate_key /etc/trap/lab.key;
    access_log /var/log/nginx/adaptive_access.json adaptive_json;

    location / {
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Real-Port $remote_port;
        proxy_set_header X-Forwarded-Port $server_port;
        proxy_set_header X-Request-ID $request_id;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_connect_timeout 5s;
        proxy_read_timeout 30s;
        proxy_intercept_errors on;
        error_page 502 503 504 = @backend_unavailable_tls;
        proxy_pass $adaptive_backend;
    }

    location @backend_unavailable_tls {
        default_type application/json;
        add_header Cache-Control no-store always;
        return 503 '{"status":"backend_unavailable","profile":"$adaptive_profile"}';
    }
}
